//! A SpecOrigin and AlignSpecOffset through a change of StdOfRest, checked
//! against the C library.
//!
//! `spec_origin_sor_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/spec_origin_sor_probe.c`. SetStdOfRest re-expresses
//! a set SpecOrigin in the new rest frame with a conversion from the Frame
//! to a copy of it, AlignSpecOffset included, and raises AST__ATSER when the
//! result is bad (specframe.c `OriginStdOfRest`). With AlignSpecOffset set
//! on both Frames, the result's zero point is the target origin transformed
//! through the conversion (specframe.c:2953). In a wavelength system that
//! has no value when no SpecOrigin is set, and the result's own origin is
//! used instead, as upstream 65bd5b6e has it; the corpus needs that commit.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "spec_origin_sor_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::error::{AstResult, ErrorCode};
use starlink_ast::frames::FrameSearch;
use starlink_ast::frames::{
    DSBSpecFrame, Frame, FrameRef, SideBand, SpecFrame, SpecSystem, StdOfRest,
};

/// The probe's Frame, as a SpecFrame or a DSBSpecFrame.
#[derive(Clone)]
enum Spec {
    Plain(SpecFrame),
    Dsb(DSBSpecFrame),
}

impl Spec {
    fn spec_mut(&mut self) -> &mut SpecFrame {
        match self {
            Spec::Plain(f) => f,
            Spec::Dsb(f) => f.spec_mut(),
        }
    }
    fn spec(&self) -> &SpecFrame {
        match self {
            Spec::Plain(f) => f,
            Spec::Dsb(f) => f.spec(),
        }
    }
    fn frame(&self) -> &dyn Frame {
        match self {
            Spec::Plain(f) => f,
            Spec::Dsb(f) => f,
        }
    }
}

fn build(class: &str, system: &str, offset: bool, origin: Option<f64>, value: f64) -> Spec {
    let (sys, unit) = match system {
        "System=WAVE,Unit=Angstrom" => (SpecSystem::Wavelen, "Angstrom"),
        "System=FREQ,Unit=GHz" => (SpecSystem::Freq, "GHz"),
        other => panic!("no Rust set-up for {other}"),
    };
    let mut f = match class {
        "SpecFrame" => Spec::Plain(SpecFrame::new(sys)),
        "DSBSpecFrame" => Spec::Dsb(DSBSpecFrame::new(sys)),
        other => panic!("no Rust set-up for {other}"),
    };
    let s = f.spec_mut();
    Frame::set_unit(s, 1, unit).unwrap();
    s.set_std_of_rest(StdOfRest::Lsrk).unwrap();
    s.set_epoch_year(2005.0);
    s.set_ref_pos(None, 2.6, 0.35).unwrap();
    if let Spec::Dsb(d) = &mut f {
        d.set_if_ghz(4.0);
        d.set_sideband(SideBand::LSB);
        d.set_align_sideband(true);
        d.set_dsb_centre_cur(value).unwrap();
    }
    let s = f.spec_mut();
    s.set_align_spec_offset(offset);
    if let Some(o) = origin {
        s.set_spec_origin_cur(o).unwrap();
    }
    f
}

fn outcome<T>(r: AstResult<T>) -> Result<T, String> {
    r.map_err(|e| match e.code() {
        ErrorCode::Atser => "Atser".to_string(),
        code => format!("{code:?}"),
    })
}

/// Set StdOfRest=HELIO on a copy, giving its SpecOrigin.
fn set_helio(f: &Spec) -> AstResult<Option<f64>> {
    let mut g = f.clone();
    g.spec_mut().set_std_of_rest(StdOfRest::Heliocentric)?;
    let s = g.spec();
    Ok(if s.test_spec_origin() {
        Some(s.spec_origin_cur()?)
    } else {
        None
    })
}

/// Convert to a copy whose StdOfRest is HELIO, giving the converted value.
fn convert(f: &Spec, origin: Option<f64>, value: f64) -> AstResult<Option<f64>> {
    let mut h = f.clone();
    h.spec_mut().clear_spec_origin();
    h.spec_mut().set_std_of_rest(StdOfRest::Heliocentric)?;
    if let Some(o) = origin {
        h.spec_mut().set_spec_origin_cur(o)?;
    }
    let Some(fs) = f
        .frame()
        .snapshot()
        .convert_to(h.frame().snapshot().as_mut(), &[])?
    else {
        return Ok(None);
    };
    let map = fs.mapping(FrameRef::Base, FrameRef::Current)?;
    let out = map.transform(&PointSet::from_rows([[value]]), true)?;
    Ok(Some(out.point(0)[0]))
}

#[test]
fn origin_through_rest_frame_change_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(class, system, offset, origin, value, want_set, want_conv) in cases::CASES {
        let f = build(class, system, offset, origin, value);
        let got = (outcome(set_helio(&f)), outcome(convert(&f, origin, value)));
        let want = (
            want_set.map_err(str::to_string),
            want_conv.map_err(str::to_string),
        );
        if got != want {
            failures.push(format!(
                "{class} [{system}] offset={offset} origin={origin:?}: got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
